const j = $input.first().json;
const tok = (j.headers && (j.headers['x-token'] || j.headers['X-Token'])) || '';
if (tok !== '__NOTIFY_TOKEN__') return [];   // 설치 명령이 실제 토큰으로 바꿔 넣습니다
const text = String((j.body && j.body.text) || '').slice(0, 3500);
if (!text) return [];
return [{ json: { text: '🛠 @@BRAND@@ 운영\n' + text } }];
